import random
import time

WEEKS = 7
GOLFERS = 50
GROUPS = 10
GROUP_SIZE = 5

def generate_random_schedule():
    schedule = []
    for w in range(WEEKS):
        players = list(range(GOLFERS))
        random.shuffle(players)
        week = [-1] * GOLFERS
        for g in range(GROUPS):
            for i in range(GROUP_SIZE):
                week[players[g * GROUP_SIZE + i]] = g
        schedule.append(week)
    return schedule

def compute_cost(schedule):
    # Count number of repeated pairs
    pair_weeks = {}
    for w in range(WEEKS):
        for p1 in range(GOLFERS):
            for p2 in range(p1+1, GOLFERS):
                if schedule[w][p1] == schedule[w][p2]:
                    pair = (p1, p2)
                    if pair in pair_weeks:
                        pair_weeks[pair] += 1
                    else:
                        pair_weeks[pair] = 1

    cost = 0
    for pair, count in pair_weeks.items():
        if count > 1:
            cost += count - 1
    return cost, pair_weeks

def local_search(max_iterations=100000):
    schedule = generate_random_schedule()
    cost, pair_weeks = compute_cost(schedule)

    if cost == 0:
        return schedule

    for iteration in range(max_iterations):
        # Try a random swap within a week
        w = random.randint(0, WEEKS-1)
        p1 = random.randint(0, GOLFERS-1)
        p2 = random.randint(0, GOLFERS-1)

        if p1 == p2 or schedule[w][p1] == schedule[w][p2]:
            continue

        # Evaluate the swap
        old_cost = cost

        # Temporarily swap
        g1, g2 = schedule[w][p1], schedule[w][p2]
        schedule[w][p1], schedule[w][p2] = g2, g1

        new_cost, new_pair_weeks = compute_cost(schedule)

        if new_cost <= cost:
            cost = new_cost
            pair_weeks = new_pair_weeks
            if cost == 0:
                return schedule
        else:
            # Revert
            schedule[w][p1], schedule[w][p2] = g1, g2

        if iteration % 10000 == 0:
            print(f"Iteration {iteration}, cost: {cost}")

    return None

print("Starting local search...")
start = time.time()
result = local_search(50000)
end = time.time()
print(f"Time: {end - start:.2f}s")
if result:
